// F3 回診提醒：找出今天該發的提醒（09:00 → 前 7/3/1 天；20:00 → 回診當天晚上記醫囑）
const cfg = $('提醒設定').first().json;
const clean = (name) => $(name).all().map(i => i.json).filter(r => r && Object.keys(r).length > 0);
const appts = clean('提醒｜讀取 appointments');
const members = clean('提醒｜讀取 Members');
const families = clean('提醒｜讀取 Families');
const links = clean('提醒｜讀取 FamilyPatients');
const logs = clean('提醒｜讀取 notification_log');

const TZ = 'Asia/Taipei';
const WEEK = ['一', '二', '三', '四', '五', '六', '日'];
const BLUE = '#1E6FD9';
const s = (v) => (v === undefined || v === null ? '' : String(v).trim());
function normDate(v) {
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30', { zone: TZ }).plus({ days: v }).toISODate();
  const dt = DateTime.fromISO(s(v).replace(/\//g, '-'), { zone: TZ });
  return dt.isValid ? dt.toISODate() : s(v);
}
const today = s(cfg.TEST_TODAY)
  ? DateTime.fromISO(s(cfg.TEST_TODAY), { zone: TZ }).startOf('day')
  : DateTime.now().setZone(TZ).startOf('day');
const mode = s(cfg.MODE) || 'morning';
const offsets = mode === 'evening' ? [0] : [7, 3, 1];

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
});
const alreadySent = (apptId, userId, offset) => logs.some((l) =>
  s(l.appt_id) === apptId && s(l.user_id) === userId && s(l.channel) === 'line' &&
  Number(l.offset_days) === offset && s(l.status) === 'sent');

function fmtDate(d) {
  const dt = DateTime.fromISO(d, { zone: TZ });
  return `${dt.toFormat('M/d')}（${WEEK[dt.weekday - 1]}）`;
}

function reminder(a, offset, patientName, isFamily) {
  const who = isFamily && patientName ? `${patientName}` : '你';
  const place = `${a.hospital} ${a.department}`.trim();
  if (offset === 0) {
    return [{ type: 'text', text: `${isFamily ? patientName + '今天' : '今天'}看診辛苦了！\n醫師交代了什麼？\n請留存這次看診的醫囑。` }];
  }
  const title = offset === 1 ? '明天要回診' : `${offset} 天後要回診`;
  const bubble = {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: BLUE, paddingAll: '16px', contents: [
      { type: 'text', text: `回診提醒：${title}`, color: '#FFFFFF', size: 'lg', weight: 'bold', wrap: true },
    ] },
    body: { type: 'box', layout: 'vertical', spacing: 'md', contents: [
      ...(isFamily ? [{ type: 'text', text: `${who}的回診`, size: 'md', color: '#555555' }] : []),
      { type: 'text', text: fmtDate(a.date), size: 'xxl', weight: 'bold', color: '#222222' },
      { type: 'text', text: /^\d{2}:\d{2}$/.test(a.session) ? `時間 ${a.session}` : (a.session || '—'), size: 'lg', color: '#222222' },
      { type: 'text', text: place, size: 'lg', color: '#222222', wrap: true },
      ...(offset === 1 ? [{ type: 'text', text: '記得帶健保卡', size: 'md', color: '#555555', margin: 'md' }] : []),
    ] },
  };
  if (offset === 1 && s(cfg.LIFF_SUMMARY_URL)) {
    bubble.footer = { type: 'box', layout: 'vertical', contents: [
      { type: 'button', style: 'primary', color: BLUE, height: 'md', action: { type: 'uri', label: '出示摘要', uri: s(cfg.LIFF_SUMMARY_URL) } },
    ] };
  }
  return [{ type: 'flex', altText: `回診提醒：${title}，${fmtDate(a.date)} ${a.session} ${place}`, contents: bubble }];
}

const out = [];
for (const raw of appts) {
  const a = { appt_id: s(raw.appt_id), patient_id: s(raw.patient_id), date: normDate(raw.date),
    session: s(raw.session), hospital: s(raw.hospital), department: s(raw.department), status: s(raw.status) };
  if (!['scheduled', 'edit_hospital'].includes(a.status)) continue;
  const dt = DateTime.fromISO(a.date, { zone: TZ });
  if (!dt.isValid) continue;
  const offset = Math.round(dt.startOf('day').diff(today, 'days').days);
  if (!offsets.includes(offset)) continue;

  if (!a.appt_id || !a.patient_id) continue;
  const matches = links.filter(r => s(r.patientId) === a.patient_id);
  if (matches.length !== 1 || !s(matches[0].familyId)) continue;
  const familyId = s(matches[0].familyId);
  if (links.filter(r => s(r.familyId) === familyId).length !== 1) continue;
  const family = families.filter(r => s(r.familyId) === familyId);
  if (family.length !== 1) continue;
  const patientName = s(family[0].patientName);
  const recipients = members.filter(r => s(r.familyId) === familyId && s(r.lineUid) &&
    members.filter(m => s(m.lineUid) === s(r.lineUid)).length === 1);
  const seen = new Set();
  for (const r of recipients) {
    const uid = s(r.lineUid), to = uid;
    if (!to || seen.has(uid)) continue;
    seen.add(uid);
    if (alreadySent(a.appt_id, uid, offset)) continue;
    out.push({ json: {
      to, retryKey: uuid(),
      messages: reminder(a, offset, patientName, true),
      log: { appt_id: a.appt_id, user_id: uid, channel: 'line', offset_days: offset },
    } });
  }
}
return out;
